<?php require_once __DIR__.'/includes/functions.php';require_login();if($_SERVER['REQUEST_METHOD']!=='POST'){redirect('dashboard.php');}verify_csrf();$id=(int)($_POST['id']??0);$s=db()->prepare("UPDATE reservations SET status='cancelled',updated_at=NOW() WHERE id=? AND customer_id=? AND status='pending'");$s->execute([$id,current_user()['id']]);if($s->rowCount()){flash('success','Reservation request cancelled.');log_activity('Cancelled reservation #'.$id);}else{flash('warning','Only your pending reservations can be cancelled.');}redirect('dashboard.php');
